Declaration.Header:
    {{ header.declaration_type }}
    {{ header.customs_office }}
{%- for role, party in [("Exporter", header.exporter), ("Importer", header.importer), ("Declarant", header.declarant)] %}
    <{{ role }}>
      {{ party.name }}
      {{ party.address }}
      {{ party.country }}
      {{ party.tax_id }}
    </{{ role }}>
{%- endfor %}


    {{ header.currency }}
    {{ header.country_of_dispatch }}
    {{ header.country_of_destination }}
    {{ header.transport_mode }}

Declaration.Shipment:
{%- for number in shipment.invoice_numbers %}
    {{ number }}
{%- endfor %}
    {{ shipment.invoice_date }}
    {{ shipment.transport_document }}
    {{ shipment.vehicle_id }}
    {{ shipment.total_invoice_value|num(2) }}
    {{ shipment.total_packages }}
    {{ shipment.total_gross_weight_kg|num(3) }}
    {{ shipment.total_net_weight_kg|num(3) }}

Declaration.Items:
{%- for item in items %}


      {{ item.description }}
      {{ item.article }}
      {{ item.hs_code }}
      {{ item.country_of_origin }}
      {{ item.quantity }}
      {{ item.packages }}
      {{ item.gross_weight_kg|num(3) }}
      {{ item.net_weight_kg|num(3) }}
      {{ item.unit_price|num(2) }}
      {{ item.total_value|num(2) }}

{%- endfor %}
